'use strict';

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const N = input[0];
const K = input[1];
const sizes = input.slice(2).sort((a, b) => a - b);

const INF = Infinity;
let prev2 = new Float64Array(K + 1);
prev2.fill(INF);

let prev1 = new Float64Array(K + 1);
prev1.fill(INF);
prev1[0] = 0;

let current = new Float64Array(K + 1);

for (let i = 1; i <= N; i++) {
  for (let j = 0; j <= K; j++) {
    current[j] = prev1[j];
  }

  if (i >= 2) {
    const gap = sizes[i - 1] - sizes[i - 2];
    const cost = gap * gap;
    const maxPairs = Math.min(K, Math.floor(i / 2));

    for (let j = 1; j <= maxPairs; j++) {
      const deadline = N - 3 * (K - j) - 1;
      if (i <= deadline) {
        const candidate = prev2[j - 1] + cost;
        if (candidate < current[j]) current[j] = candidate;
      }
    }
  }

  const temp = prev2;
  prev2 = prev1;
  prev1 = current;
  current = temp;
}

console.log(String(prev1[K]));
